<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Explainable Insights | SignalGrid</title>@vite('resources/js/app.js')</head><body class="domain-body"><main class="domain-shell"><header class="domain-header"><div><span class="eyebrow">EVIDENCE-BASED DECISIONS</span><h1>Explainable insights</h1><p>Every conclusion shows evidence, thresholds, confidence, recommendation and limitations.</p></div><a class="secondary" href="{{ route('dashboard') }}">Dashboard</a></header><section class="insight-real-grid">@forelse($insights as $insight)<article class="panel insight-real-card"><header><span class="sev {{ $insight->severity==='high'?'high':($insight->severity==='medium'?'med':'low') }}">{{ ucfirst($insight->severity) }}</span><div><small>{{ $insight->rule->code }} · {{ strtoupper($insight->confidence) }} CONFIDENCE</small><h2>{{ $insight->title }}</h2><p>{{ optional($insight->floor->building)->name }} · {{ optional($insight->floor)->name }}</p></div><em>{{ ucfirst($insight->status) }}</em></header><div class="insight-evidence">@foreach($insight->evidence as $key=>$value)<div><small>{{ str_replace('_',' ',ucfirst($key)) }}</small><b>{{ $value }}</b></div>@endforeach</div><section><h4>Identified problem</h4><p>{{ $insight->classification }}</p></section><section><h4>Recommended action</h4><p>{{ $insight->recommendation }}</p></section>@if($insight->limitations)<section class="limitation"><strong>Limitations</strong><p>{{ implode(' ',array_filter($insight->limitations)) }}</p></section>@endif<footer><span>{{ $insight->period_start->format('d M') }} to {{ $insight->period_end->format('d M Y') }}</span><span>{{ $insight->actions->count() }} action item(s)</span></footer></article>@empty<div class="panel domain-empty"><h2>No insights generated</h2><p>Generate insights from a survey after real measurements are available.</p></div>@endforelse</section>{{ $insights->links() }}</main></body></html>